FILES = [('app/reports/dashboard_eligibility.py', '497efc9f50ff92efde2db1f082e89c772885d4a7939ebb49b71ab3fe58789e92', '"""Dashboard admission uses the same mass criterion as scoring."""\nfrom dataclasses import dataclass\nfrom app.scoring.selection_policy import qualifies, mass_kg, piece_count\n\n@dataclass\nclass DashboardEligibility:\n    eligible: bool\n    reason: str\n    qualifying_position: dict | None = None\n\ndef evaluate_dashboard_tender(tender):\n    if not tender.get(\'analysis_done\') or tender.get(\'status\') not in (\'can_apply\', \'manual_review\', \'needs_clarification\'):\n        return DashboardEligibility(False, \'analysis_not_approved\')\n    if tender.get(\'processing_status\') != \'analyzed\':\n        return DashboardEligibility(False, \'analysis_not_completed\')\n    for pos in tender.get(\'positions\') or []:\n        if qualifies(pos):\n            mass = mass_kg(pos)\n            reason = f\'position_weight_ok:{mass:g}kg\' if mass is not None else f\'position_pieces_ok:{piece_count(pos):g}pcs\'\n            return DashboardEligibility(True, reason, pos)\n    return DashboardEligibility(False, \'no_single_position_above_threshold\')\n'), ('app/reports/active_tenders.py', '6882a1b0f48ceb529ba08a0fdfa163a989884f41de2617151f35c7caa6099e9b', '"""Unified HTTP/Excel tender report for v6.2.\n\nShows:\n1. fully analysed tenders from TenderItem;\n2. ingested/failed/waiting tenders from source raw_payload positions.\n\nOne output row = one tender position.\n"""\n\nfrom io import BytesIO\nfrom datetime import datetime, timezone\nfrom zoneinfo import ZoneInfo\nfrom app.reports.review_dismissals import is_dismissed\nfrom app.scoring.selection_policy import price_priority, qualifies, mass_kg, material_status\nfrom typing import Any\n\nfrom sqlalchemy import select\nfrom sqlalchemy.orm import joinedload\n\nfrom app.reports.dashboard_eligibility import (\n    evaluate_dashboard_tender,\n)\nfrom app.core.logging import get_logger\nfrom app.db.session import SyncSessionLocal\nfrom app.models.database import Lot, Tender, TenderStatus\n\n\nlogger = get_logger(__name__)\n\n\nREPORT_STATUSES = {\n    TenderStatus.CAN_APPLY,\n    TenderStatus.NEEDS_CLARIFICATION,\n    TenderStatus.MANUAL_REVIEW,\n}\n\n\ndef _value(obj: Any) -> Any:\n    return obj.value if hasattr(obj, "value") else obj\n\n\ndef _deadline(tender: Tender) -> str:\n    if not tender.submission_deadline:\n        return ""\n\n    dt = tender.submission_deadline\n    if dt.tzinfo is None: dt = dt.replace(tzinfo=timezone.utc)\n    return dt.astimezone(ZoneInfo(\'Europe/Moscow\')).strftime(\n        "%d.%m.%Y %H:%M"\n    )\n\n\ndef _source_relevance(tender: Tender) -> dict:\n    """Return stored relevance or safely rebuild it from source positions."""\n\n    raw = tender.raw_payload or {}\n\n    if not isinstance(raw, dict):\n        return {}\n\n    public = raw.get("public") or {}\n\n    if isinstance(public, dict):\n        relevance = public.get("relevance")\n\n        if isinstance(relevance, dict) and relevance:\n            return relevance\n\n    relevance = raw.get("relevance")\n\n    if isinstance(relevance, dict) and relevance:\n        return relevance\n\n    positions = raw.get("positions") or []\n\n    if not isinstance(positions, list) or not positions:\n        return {}\n\n    try:\n        from app.sources.tender_pro.relevance import (\n            analyse_tender_positions,\n        )\n\n        return analyse_tender_positions(positions)\n\n    except Exception as exc:\n        logger.warning(\n            "report_relevance_rebuild_failed",\n            tender_id=str(tender.id),\n            error=str(exc),\n        )\n        return {}\n\n\ndef _source_positions(tender: Tender) -> list[dict]:\n    raw = tender.raw_payload or {}\n\n    if not isinstance(raw, dict):\n        return []\n\n    positions = raw.get("positions") or []\n\n    return [\n        item\n        for item in positions\n        if isinstance(item, dict)\n    ]\n\n\ndef _base_row(t: Tender) -> dict:\n    relevance = _source_relevance(t)\n\n    processing_status = _value(\n        t.processing_status\n    ) or ""\n\n    status = _value(t.status) or ""\n\n    if t.analysis_done:\n        analysis_state = "Готов"\n    elif str(processing_status).upper() == "FAILED":\n        analysis_state = "Ошибка анализа"\n    else:\n        analysis_state = "Ожидает анализа"\n\n    return {\n        "id": str(t.id),\n        "external_id": t.external_id,\n        "source": t.source,\n        "title": t.title,\n        "customer_name": t.customer_name or "",\n        "customer_inn": t.customer_inn or "",\n        "law_type": _value(t.law_type) or "",\n        "status": status,\n        "score": t.score or 0,\n        "amount": (\n            float(t.amount)\n            if t.amount is not None\n            else None\n        ),\n        "currency": t.currency or "RUB",\n        "price_priority": price_priority(t.amount,t.currency),\n        "deadline_timezone": "Europe/Moscow",\n        "region": t.region or "",\n        "delivery_place": t.delivery_place or "",\n        "source_url": t.source_url or "",\n        "submission_deadline": _deadline(t),\n        "processing_status": processing_status,\n        "analysis_done": bool(t.analysis_done),\n        "analysis_state": analysis_state,\n        "analysis_version": t.analysis_version or "",\n        "notified_bitrix": bool(\n            getattr(t, "notified_bitrix", False)\n        ),\n        "notified_telegram": bool(\n            getattr(t, "notified_telegram", False)\n        ),\n        "relevant_weight_kg": relevance.get(\n            "relevant_weight_kg"\n        ),\n        "weight_status": relevance.get(\n            "weight_status"\n        ) or "",\n        "matched_count": relevance.get(\n            "matched_count"\n        ) or 0,\n    }\n\n\ndef get_active_tenders() -> list[dict]:\n    """Return active relevant tenders for HTTP and Excel.\n\n    Analysed tenders use normalized TenderItem rows.\n    Not-yet-analysed tenders fall back to raw source positions.\n    """\n\n    try:\n        with SyncSessionLocal() as session:\n            stmt = (\n                select(Tender)\n                .where(Tender.is_active.is_(True))\n                .options(\n                    joinedload(Tender.lots)\n                    .joinedload(Lot.items),\n                    joinedload(Tender.decisions),\n                )\n                .order_by(\n                    Tender.analysis_done.desc(),\n                    Tender.score.desc(),\n                    Tender.submission_deadline.asc(),\n                )\n            )\n\n            tenders = (\n                session.execute(stmt)\n                .unique()\n                .scalars()\n                .all()\n            )\n\n            rows: list[dict] = []\n\n            for t in tenders:\n                if is_dismissed(t.source,t.external_id):continue\n                deadline=t.submission_deadline\n                if deadline is None or (deadline.replace(tzinfo=timezone.utc) if deadline.tzinfo is None else deadline)<=datetime.now(timezone.utc):continue\n                from app.sources.eis_freshness import eligibility\n                if eligibility(t.source, deadline, t.raw_payload, t.is_active) is not None:continue\n                # Do not expose analysed tenders which AI has\n                # explicitly classified outside the report statuses.\n                if (\n                    t.analysis_done\n                    and t.status not in REPORT_STATUSES\n                ):\n                    continue\n\n                decision = (\n                    max(\n                        t.decisions,\n                        key=lambda x: x.created_at,\n                    )\n                    if t.decisions\n                    else None\n                )\n\n                base = _base_row(t)\n\n                normalized_items = []\n\n                for lot in t.lots or []:\n                    for item in lot.items or []:\n                        normalized_items.append(\n                            (lot, item)\n                        )\n\n                # -----------------------------------------\n                # Fully normalized LLM/analysis positions\n                # -----------------------------------------\n                if normalized_items:\n                    for lot, item in normalized_items:\n                        row = dict(base)\n\n                        row.update({\n                            "lot_number":\n                                lot.lot_number or "",\n                            "position_number":\n                                item.position_number,\n                            "product_name":\n                                item.name or "",\n                            "product_type":\n                                item.product_type or "",\n                            "alloy":\n                                item.alloy or "",\n                            "temper":\n                                item.temper or "",\n                            "thickness_mm":\n                                item.thickness_mm,\n                            "width_mm":\n                                item.width_mm,\n                            "length_mm":\n                                item.length_mm,\n                            "diameter_mm":\n                                item.diameter_mm,\n                            "quantity":\n                                item.quantity,\n                            "unit":\n                                item.unit or "",\n                            "mass_kg":\n                                item.mass_kg,\n                            "standard":\n                                item.standard or "",\n                            "delivery_place":\n                                item.delivery_place\n                                or lot.delivery_place\n                                or t.delivery_place\n                                or "",\n                            "delivery_term":\n                                item.delivery_term or "",\n                            "payment_terms":\n                                item.payment_terms or "",\n                            "can_supply":\n                                item.can_supply,\n                            "supply_reason":\n                                item.supply_reason or "",\n                            "reasons":\n                                decision.reasons\n                                if decision else [],\n                            "risks":\n                                decision.risks\n                                if decision else [],\n                            "model_version":\n                                decision.model_version\n                                if decision\n                                else t.analysis_version or "",\n                            "position_source":\n                                "analysis",\n                        })\n\n                        rows.append(row)\n\n                    continue\n\n                # -----------------------------------------\n                # Source positions before successful LLM\n                # -----------------------------------------\n                source_positions = _source_positions(t)\n\n                if source_positions:\n                    for number, item in enumerate(\n                        source_positions,\n                        1,\n                    ):\n                        row = dict(base)\n\n                        quantity = item.get("quantity")\n                        unit = item.get("unit") or ""\n\n                        mass_kg = None\n\n                        try:\n                            if quantity not in (None, ""):\n                                q = float(\n                                    str(quantity)\n                                    .replace(",", ".")\n                                )\n\n                                u = str(unit).lower().strip()\n\n                                if u in (\n                                    "кг",\n                                    "kg",\n                                    "килограмм",\n                                    "килограммы",\n                                ):\n                                    mass_kg = q\n\n                                elif u in (\n                                    "т",\n                                    "тн",\n                                    "тонн",\n                                    "тонна",\n                                    "ton",\n                                    "tons",\n                                ):\n                                    mass_kg = q * 1000\n                        except (\n                            TypeError,\n                            ValueError,\n                        ):\n                            mass_kg = None\n\n                        row.update({\n                            "lot_number": "",\n                            "position_number":\n                                item.get(\n                                    "position_number"\n                                )\n                                or item.get(\n                                    "position_id"\n                                )\n                                or number,\n                            "product_name":\n                                item.get("name") or "",\n                            "product_type": "",\n                            "alloy": "",\n                            "temper": "",\n                            "thickness_mm": None,\n                            "width_mm": None,\n                            "length_mm": None,\n                            "diameter_mm": None,\n                            "quantity": quantity,\n                            "unit": unit,\n                            "mass_kg": mass_kg,\n                            "standard": "",\n                            "delivery_term": "",\n                            "payment_terms": "",\n                            "can_supply": None,\n                            "supply_reason":\n                                "Ожидает LLM-анализа",\n                            "reasons": [],\n                            "risks": [],\n                            "model_version":\n                                t.analysis_version or "",\n                            "position_source":\n                                "source",\n                        })\n\n                        rows.append(row)\n\n                    continue\n\n                # Tender without positions: keep visible.\n                row = dict(base)\n\n                row.update({\n                    "lot_number": "",\n                    "position_number": "",\n                    "product_name": "",\n                    "product_type": "",\n                    "alloy": "",\n                    "temper": "",\n                    "thickness_mm": None,\n                    "width_mm": None,\n                    "length_mm": None,\n                    "diameter_mm": None,\n                    "quantity": None,\n                    "unit": "",\n                    "mass_kg": None,\n                    "standard": "",\n                    "delivery_term": "",\n                    "payment_terms": "",\n                    "can_supply": None,\n                    "supply_reason":\n                        "Позиции отсутствуют",\n                    "reasons": [],\n                    "risks": [],\n                    "model_version":\n                        t.analysis_version or "",\n                    "position_source": "tender",\n                })\n\n                rows.append(row)\n\n            return rows\n\n    except Exception as exc:\n        logger.exception(\n            "get_active_tenders_failed",\n            error=str(exc),\n        )\n        return []\n\n\ndef get_all_tenders_stats() -> dict:\n    try:\n        with SyncSessionLocal() as session:\n            all_tenders = (\n                session.execute(\n                    select(Tender)\n                )\n                .scalars()\n                .all()\n            )\n\n            return {\n                "total": len(all_tenders),\n                "active": sum(\n                    bool(t.is_active)\n                    for t in all_tenders\n                ),\n                "analyzed": sum(\n                    bool(t.analysis_done)\n                    for t in all_tenders\n                ),\n                "can_apply": sum(\n                    t.status == TenderStatus.CAN_APPLY\n                    for t in all_tenders\n                ),\n                "manual_review": sum(\n                    t.status in (\n                        TenderStatus.MANUAL_REVIEW,\n                        TenderStatus.NEEDS_CLARIFICATION,\n                    )\n                    for t in all_tenders\n                ),\n                "not_analyzed_yet": sum(\n                    not t.analysis_done\n                    for t in all_tenders\n                ),\n            }\n\n    except Exception as exc:\n        logger.exception(\n            "get_stats_failed",\n            error=str(exc),\n        )\n        return {}\n\n\ndef generate_excel_report(\n    tenders: list[dict],\n) -> bytes:\n    import openpyxl\n    from openpyxl.styles import (\n        Alignment,\n        Font,\n        PatternFill,\n    )\n    from openpyxl.utils import get_column_letter\n\n    wb = openpyxl.Workbook()\n    ws = wb.active\n    ws.title = "Тендерные позиции"\n\n    headers = [\n        "№",\n        "Источник",\n        "Внешний ID",\n        "Заказчик",\n        "ИНН",\n        "Предмет закупки",\n        "Срок подачи",\n        "Регион",\n        "Место поставки",\n        "Позиция",\n        "Наименование",\n        "Тип продукции",\n        "Сплав",\n        "Состояние",\n        "Толщина, мм",\n        "Ширина, мм",\n        "Длина, мм",\n        "Диаметр, мм",\n        "Количество",\n        "Ед.",\n        "Масса позиции, кг",\n        "Релевантная масса тендера, кг",\n        "Весовой статус",\n        "ГОСТ/ТУ",\n        "Релевантная позиция",\n        "Score первичного фильтра",\n        "Сплав по фильтру",\n        "Состояние по фильтру",\n        "Можем поставить",\n        "Причина по позиции",\n        "Статус анализа",\n        "Статус ИИ",\n        "Балл",\n        "Bitrix24",\n        "Ссылка",\n        "Причины решения",\n        "Риски",\n        "Версия анализа",\n    ]\n\n    fill = PatternFill(\n        "solid",\n        fgColor="1F4E79",\n    )\n\n    font = Font(\n        color="FFFFFF",\n        bold=True,\n    )\n\n    for column, header in enumerate(\n        headers,\n        1,\n    ):\n        cell = ws.cell(\n            1,\n            column,\n            header,\n        )\n\n        cell.fill = fill\n        cell.font = font\n        cell.alignment = Alignment(\n            horizontal="center",\n            vertical="center",\n            wrap_text=True,\n        )\n\n    for index, tender in enumerate(\n        tenders,\n        1,\n    ):\n        can_supply = tender.get(\n            "can_supply"\n        )\n\n        if can_supply is True:\n            can_supply_text = "Да"\n        elif can_supply is False:\n            can_supply_text = "Нет"\n        else:\n            can_supply_text = "Уточнить"\n\n        bitrix = (\n            "Отправлено"\n            if tender.get("notified_bitrix")\n            else "Не отправлено"\n        )\n\n        try:\n            from app.sources.tender_pro.relevance import (\n                analyse_position,\n            )\n\n            pre_filter = analyse_position(\n                tender.get("product_name") or ""\n            ) or {}\n\n        except Exception:\n            pre_filter = {}\n\n        pre_filter_relevant = (\n            "Да"\n            if pre_filter.get("relevant")\n            else "Нет"\n        )\n\n        pre_filter_score = pre_filter.get(\n            "score",\n            0,\n        )\n\n        pre_filter_alloys = ", ".join(\n            pre_filter.get("alloys") or []\n        )\n\n        pre_filter_tempers = ", ".join(\n            pre_filter.get("tempers") or []\n        )\n\n        values = [\n            index,\n            tender.get("source"),\n            tender.get("external_id"),\n            tender.get("customer_name"),\n            tender.get("customer_inn"),\n            tender.get("title"),\n            tender.get("submission_deadline"),\n            tender.get("region"),\n            tender.get("delivery_place"),\n            tender.get("position_number"),\n            tender.get("product_name"),\n            tender.get("product_type"),\n            tender.get("alloy"),\n            tender.get("temper"),\n            tender.get("thickness_mm"),\n            tender.get("width_mm"),\n            tender.get("length_mm"),\n            tender.get("diameter_mm"),\n            tender.get("quantity"),\n            tender.get("unit"),\n            tender.get("mass_kg"),\n            tender.get("relevant_weight_kg"),\n            tender.get("weight_status"),\n            tender.get("standard"),\n            pre_filter_relevant,\n            pre_filter_score,\n            pre_filter_alloys,\n            pre_filter_tempers,\n            can_supply_text,\n            tender.get("supply_reason"),\n            tender.get("analysis_state"),\n            tender.get("status"),\n            tender.get("score"),\n            bitrix,\n            tender.get("source_url"),\n            "; ".join(\n                tender.get("reasons") or []\n            ),\n            "; ".join(\n                tender.get("risks") or []\n            ),\n            tender.get("model_version"),\n        ]\n\n        for column, value in enumerate(\n            values,\n            1,\n        ):\n            ws.cell(\n                index + 1,\n                column,\n                value,\n            )\n\n    ws.freeze_panes = "A2"\n    ws.auto_filter.ref = ws.dimensions\n\n    ws.row_dimensions[1].height = 38\n\n    for column in range(\n        1,\n        len(headers) + 1,\n    ):\n        width = min(\n            max(\n                12,\n                len(headers[column - 1]) + 2,\n            ),\n            36,\n        )\n\n        ws.column_dimensions[\n            get_column_letter(column)\n        ].width = width\n\n    # Wider text columns.\n    for column in (\n        "D",\n        "F",\n        "K",\n        "Z",\n        "AE",\n        "AF",\n        "AG",\n    ):\n        ws.column_dimensions[column].width = 38\n\n    for row in ws.iter_rows(\n        min_row=2,\n    ):\n        for cell in row:\n            cell.alignment = Alignment(\n                vertical="top",\n                wrap_text=True,\n            )\n\n    out = BytesIO()\n    wb.save(out)\n\n    return out.getvalue()\n\n\ndef format_report_text(\n    tenders: list[dict],\n) -> str:\n    if not tenders:\n        return "Активных тендеров нет."\n\n    unique = len({\n        item["id"]\n        for item in tenders\n    })\n\n    return (\n        f"Активных тендеров: {unique}; "\n        f"товарных позиций: {len(tenders)}."\n    )\n\n\nformat_report_summary = format_report_text\n\n\ndef get_tender_dashboard() -> list[dict]:\n    """\n    Aggregate position-level active tender rows into one record per tender.\n\n    Excel keeps using get_active_tenders() with one row per position.\n    HTTP dashboard uses this function with one row per tender.\n\n    Final HTTP output is additionally protected by\n    evaluate_dashboard_tender(): a tender is shown only when at least\n    one individual aluminium position satisfies the business threshold.\n    """\n\n    rows = get_active_tenders()\n\n    grouped: dict[str, dict] = {}\n\n    for row in rows:\n\n        tender_id = str(\n            row.get("id")\n            or row.get("external_id")\n            or ""\n        )\n\n        if not tender_id:\n            continue\n\n        if tender_id not in grouped:\n\n            tender = dict(row)\n\n            #\n            # Dashboard object represents the whole tender.\n            # Position-specific fields must live only inside "positions".\n            #\n            for field in (\n                "lot_number",\n                "position_number",\n                "product_name",\n                "product_type",\n                "alloy",\n                "temper",\n                "thickness_mm",\n                "width_mm",\n                "length_mm",\n                "diameter_mm",\n                "quantity",\n                "unit",\n                "mass_kg",\n                "standard",\n                "delivery_term",\n                "payment_terms",\n                "can_supply",\n                "supply_reason",\n                "position_source",\n            ):\n                tender.pop(\n                    field,\n                    None,\n                )\n\n            tender["positions"] = []\n            tender["positions_count"] = 0\n\n            #\n            # Existing source-level weight is retained only as\n            # informational metadata.\n            #\n            # Dashboard admission itself is based on ONE individual\n            # position inside evaluate_dashboard_tender().\n            #\n            tender[\n                "relevant_weight_kg"\n            ] = row.get(\n                "relevant_weight_kg"\n            )\n\n            tender[\n                "weight_status"\n            ] = row.get(\n                "weight_status"\n            )\n\n            grouped[\n                tender_id\n            ] = tender\n\n        tender = grouped[\n            tender_id\n        ]\n\n        position_name = (\n            row.get(\n                "product_name"\n            )\n            or row.get(\n                "name_product"\n            )\n            or ""\n        )\n\n        pre_filter = {}\n\n        try:\n            from app.sources.tender_pro.relevance import (\n                analyse_position,\n            )\n\n            pre_filter = (\n                analyse_position(\n                    position_name\n                )\n                or {}\n            )\n\n        except Exception as exc:\n\n            logger.warning(\n                "dashboard_position_relevance_failed",\n                tender_id=tender_id,\n                position_name=position_name,\n                error=str(exc),\n            )\n\n        position = {\n            "position_number":\n                row.get(\n                    "position_number"\n                ),\n\n            "name":\n                position_name,\n\n            "name_product":\n                position_name,\n\n            "product_type":\n                row.get(\n                    "product_type"\n                ),\n\n            "alloy":\n                row.get(\n                    "alloy"\n                ),\n\n            "temper":\n                row.get(\n                    "temper"\n                ),\n\n            "thickness_mm":\n                row.get(\n                    "thickness_mm"\n                ),\n\n            "width_mm":\n                row.get(\n                    "width_mm"\n                ),\n\n            "quantity":\n                row.get(\n                    "quantity"\n                ),\n\n            "unit":\n                row.get(\n                    "unit"\n                ),\n\n            "mass_kg":\n                row.get(\n                    "mass_kg"\n                ),\n\n            "can_supply":\n                row.get(\n                    "can_supply"\n                ),\n\n            "supply_reason":\n                row.get(\n                    "supply_reason"\n                ),\n\n            #\n            # Deterministic pre-filter result.\n            #\n            "pre_filter_relevant":\n                bool(\n                    pre_filter.get(\n                        "relevant"\n                    )\n                ),\n\n            "pre_filter_score":\n                pre_filter.get(\n                    "score",\n                    0,\n                ),\n\n            "pre_filter_products":\n                pre_filter.get(\n                    "products",\n                    [],\n                ),\n\n            "pre_filter_alloys":\n                pre_filter.get(\n                    "alloys",\n                    [],\n                ),\n\n            "pre_filter_tempers":\n                pre_filter.get(\n                    "tempers",\n                    [],\n                ),\n\n            "pre_filter_reasons":\n                pre_filter.get(\n                    "reasons",\n                    [],\n                ),\n        }\n\n        tender[\n            "positions"\n        ].append(\n            position\n        )\n\n    #\n    # Finalize position counts.\n    #\n    dashboard_candidates = list(\n        grouped.values()\n    )\n\n    for tender in dashboard_candidates:\n\n        tender[\n            "positions_count"\n        ] = len(\n            tender[\n                "positions"\n            ]\n        )\n\n    #\n    # Final HTTP eligibility gate.\n    #\n    eligible_dashboard = []\n\n    for tender in dashboard_candidates:\n\n        eligibility = (\n            evaluate_dashboard_tender(\n                tender\n            )\n        )\n\n        if not eligibility.eligible:\n\n            logger.info(\n                "dashboard_tender_filtered",\n                source=tender.get(\n                    "source"\n                ),\n                external_id=tender.get(\n                    "external_id"\n                ),\n                reason=eligibility.reason,\n            )\n\n            continue\n\n        tender[\n            "dashboard_eligibility_reason"\n        ] = eligibility.reason\n\n        tender[\'matched_count\'] = sum(qualifies(p) for p in tender[\'positions\'])\n        tender[\'relevant_weight_kg\'] = mass_kg(eligibility.qualifying_position)\n        tender[\'weight_status\'] = \'ok\' if tender[\'relevant_weight_kg\'] is not None else \'mass_unknown_pieces_ok\'\n        tender[\'participation_score\'] = tender.get(\'score\')\n        tender[\'participation_decision\'] = tender.get(\'status\')\n        tender[\'catalog_classification\'] = \'suitable\'\n        tender[\'participation_description\'] = \'; \'.join(str(x) for x in (tender.get(\'reasons\') or [])) or \'Анализ завершён. См. рекомендации по позициям.\'\n        tender[\'weight_basis\'] = \'one_qualifying_position\'\n        for position in tender[\'positions\']:\n            position[\'pre_filter_relevant\'] = material_status(position) is True\n        eligible_dashboard.append(tender)\n\n    priority_order={\'high\':0,\'normal\':1,\'price_unknown\':2,\'currency_review\':3,\'low\':4}\n    return sorted(eligible_dashboard,key=lambda t:priority_order.get(t.get(\'price_priority\'),5))\n'), ('app/reports/review_dashboard.py', '55b7bf15c5c91deff58f3fc3e49be7f8d7dcfa435979e5a4c9936e4717198ab1', '"""Read-only review inbox: DB tenders and marketplace candidates."""\nfrom datetime import datetime, timezone\nfrom sqlalchemy import select, or_\nfrom app.db.session import SyncSessionLocal\nfrom app.models.database import Tender, Decision, TenderStatus, ProcessingStatus\nfrom app.marketplace_discovery.review_store import list_review_candidates\nfrom app.marketplace_discovery.product_screening import screen_candidate\n\n\ndef assemble(rows, candidates, now=None):\n    now = now or datetime.now(timezone.utc)\n    merged = {}\n    for row in list(rows) + list(candidates):\n        row = dict(row)\n        key = (row.get(\'source\'), str(row.get(\'external_id\') or \'\'))\n        if not all(key) or key in merged:\n            continue\n        deadline = row.get(\'submission_deadline\')\n        try:\n            dt = datetime.fromisoformat(str(deadline).replace(\'Z\', \'+00:00\')) if deadline else None\n            if dt and dt.tzinfo is None: dt = dt.replace(tzinfo=timezone.utc)\n        except ValueError:\n            dt = None\n        if dt is None or dt <= now: continue\n        row[\'submission_deadline\'] = dt.isoformat() if dt else None\n        row[\'deadline_unknown\'] = dt is None\n        merged[key] = row\n    return sorted(merged.values(), key=lambda r: (r[\'deadline_unknown\'], r[\'submission_deadline\'] or \'\', r.get(\'title\') or \'\'))\n\n\ndef get_review_dashboard():\n    rows=[]\n    gpb_details={}\n    with SyncSessionLocal() as s:\n        tenders=s.execute(select(Tender).where(Tender.is_active.is_(True),\n            or_(Tender.status.in_([TenderStatus.MANUAL_REVIEW, TenderStatus.NEEDS_CLARIFICATION]),\n                Tender.processing_status.in_([ProcessingStatus.FAILED,ProcessingStatus.DOCUMENTS_PENDING,ProcessingStatus.INGESTED,ProcessingStatus.DOCUMENTS_READY,ProcessingStatus.ANALYZING])))).scalars().all()\n        ids=[t.id for t in tenders]\n        decisions={}\n        if ids:\n            for d in s.execute(select(Decision).where(Decision.tender_id.in_(ids)).order_by(Decision.created_at.desc())).scalars():\n                decisions.setdefault(str(d.tender_id), d)\n        for t in tenders:\n            raw=t.raw_payload or {}\n            if t.source == \'gpb\': gpb_details[t.external_id] = raw\n            from app.sources.eis_freshness import eligibility\n            if eligibility(t.source, t.submission_deadline, raw, t.is_active) is not None:\n                continue\n            # Explicit title-based exclusions are not pending specification checks.\n            if (raw.get(\'subject_screening\') or {}).get(\'subject_type\') in (\'works_service\',\'finished_product\'):continue\n            if t.source == \'b2b_center\':\n                screening=screen_candidate({\'source\':t.source,\'external_id\':t.external_id,\n                    \'title\':t.title,\'submission_deadline\':t.submission_deadline,\n                    \'is_active\':t.is_active,\'raw_payload\':raw})\n                if screening[\'action\']==\'reject\': continue\n            if t.source == \'gpb\':\n                # GPB subject v2 also hides previously failed/manual-review records.\n                from app.sources.gpb.relevance import screen\n                if screen({\'title\':t.title,\'raw_payload\':raw})[\'action\'] != \'review\':continue\n            d=decisions.get(str(t.id))\n            rows.append({\'source\':t.source,\'external_id\':t.external_id,\'title\':t.title,\n                \'source_url\':t.source_url,\'submission_deadline\':t.submission_deadline,\n                \'status\':getattr(t.status,\'value\',t.status),\n                \'analysis_done\':bool(t.analysis_done),\n                 \'reason\': (\'Ошибка обработки: требуется проверка исходных данных\' if t.processing_status == ProcessingStatus.FAILED\n                    else (\'; \'.join(str(x) for x in (d.reasons or [])) if d and t.analysis_done else \'Ожидается завершение автоматической обработки\'))})\n    from app.reports.gpb_dashboard import list_candidates, document_reason\n    for row in rows:\n        if row.get(\'source\') == \'gpb\':\n            row[\'reason\'] = document_reason(gpb_details.get(row[\'external_id\'], {}), row[\'reason\'])\n    candidates=list_candidates()\n    for c in list_review_candidates(500):\n        if c.get(\'source\') == \'gpb\':\n            from app.sources.gpb.relevance import screen\n            if screen(c)[\'action\'] != \'review\':\n                continue\n        screening=screen_candidate(c) if c.get(\'source\')==\'b2b_center\' else None\n        if screening and screening[\'action\']==\'reject\': continue\n        candidates.append({\'source\':c.get(\'source\'),\'external_id\':c.get(\'external_id\'),\n            \'title\':c.get(\'title\'),\'source_url\':c.get(\'source_url\'),\n            \'submission_deadline\':c.get(\'submission_deadline\'),\'status\':\'candidate\',\n            \'analysis_done\':False,\'reason\':(screening[\'message\'] if screening else None) or (c.get(\'raw_payload\') or {}).get(\'review_reason\') or \'Кандидат площадки: требуется подтвердить позиции и объём; полный анализ не выполнен\'})\n    from app.reports.review_dismissals import is_dismissed\n    items=[r for r in assemble(rows,candidates) if not is_dismissed(r["source"], r["external_id"])]\n    from app.reports.active_tenders import get_tender_dashboard\n    suitable = {(r[\'source\'], str(r[\'external_id\'])) for r in get_tender_dashboard()}\n    items = [r for r in items if (r[\'source\'], str(r[\'external_id\'])) not in suitable]\n    return {\'count\':len(items),\'tenders\':items,\'candidate_limit\':500}\n'), ('app/static/index.html', 'fbb5d8559dde6c33f1e640535916c1c12219e0c5c13070e79f5ba70469568a96', '<!DOCTYPE html>\n<html lang="ru">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Тендерный ассистент — ТДСМ</title>\n<style>\n  :root {\n    --green:  #1a7a4a;\n    --yellow: #b8860b;\n    --red:    #c0392b;\n    --grey:   #6b7280;\n    --bg:     #f4f6fa;\n    --card:   #ffffff;\n    --border: #e2e8f0;\n    --text:   #1e293b;\n    --sub:    #64748b;\n  }\n  * { box-sizing: border-box; margin: 0; padding: 0; }\n  body { font-family: \'Segoe UI\', Arial, sans-serif; background: var(--bg);\n         color: var(--text); min-height: 100vh; }\n\n  /* ── Шапка ── */\n  header { background: #1a2540; color: #fff; padding: 14px 28px;\n           display: flex; align-items: center; gap: 16px;\n           box-shadow: 0 2px 8px rgba(0,0,0,.25); }\n  header h1 { font-size: 1.2rem; font-weight: 600; }\n  header span { font-size: .85rem; color: #94a3b8; margin-left: auto; }\n\n  /* ── Вкладки ── */\n  nav { background: #fff; border-bottom: 1px solid var(--border);\n        padding: 0 28px; display: flex; gap: 4px; }\n  nav button { padding: 12px 20px; border: none; background: none; cursor: pointer;\n               font-size: .95rem; color: var(--sub); border-bottom: 3px solid transparent;\n               transition: all .15s; font-weight: 500; }\n  nav button.active { color: #1a2540; border-bottom-color: #1a2540; }\n  nav button:hover:not(.active) { color: var(--text); background: #f8fafc; }\n\n  /* ── Основная область ── */\n  main { padding: 24px 28px; max-width: 1400px; margin: 0 auto; }\n\n  /* ── Панель ── */\n  .panel { display: none; }\n  .panel.active { display: block; }\n\n  /* ── Карточки-статистика ── */\n  .stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px,1fr));\n           gap: 16px; margin-bottom: 24px; }\n  .stat { background: var(--card); border-radius: 10px; padding: 18px 20px;\n          border-left: 4px solid var(--border); box-shadow: 0 1px 4px rgba(0,0,0,.06); }\n  .stat.green { border-left-color: var(--green); }\n  .stat.yellow { border-left-color: var(--yellow); }\n  .stat.red { border-left-color: var(--red); }\n  .stat .num { font-size: 2rem; font-weight: 700; }\n  .stat .lbl { font-size: .82rem; color: var(--sub); margin-top: 4px; }\n\n  /* ── Таблица тендеров ── */\n  .table-wrap { background: var(--card); border-radius: 10px;\n                box-shadow: 0 1px 4px rgba(0,0,0,.06); overflow: hidden; }\n  .table-toolbar { padding: 14px 18px; display: flex; gap: 10px; align-items: center;\n                   border-bottom: 1px solid var(--border); flex-wrap: wrap; }\n  .table-toolbar input, .table-toolbar select {\n    padding: 7px 12px; border: 1px solid var(--border); border-radius: 6px;\n    font-size: .9rem; }\n  .table-toolbar input { flex: 1; min-width: 200px; }\n  table { width: 100%; border-collapse: collapse; font-size: .88rem; }\n  th { background: #f1f5f9; padding: 10px 12px; text-align: left;\n       font-weight: 600; color: var(--sub); white-space: nowrap;\n       border-bottom: 1px solid var(--border); }\n  td { padding: 10px 12px; border-bottom: 1px solid #f0f4f8; vertical-align: middle; }\n  tr:last-child td { border-bottom: none; }\n  tr:hover td { background: #f8fafc; }\n\n  /* ── Бейджи срока ── */\n  .deadline { display: inline-block; padding: 3px 9px; border-radius: 20px;\n              font-size: .8rem; font-weight: 600; white-space: nowrap; }\n  .deadline.urgent  { background: #fee2e2; color: #991b1b; }   /* < 3 дней */\n  .deadline.warning { background: #fef9c3; color: #854d0e; }   /* 3–7 дней */\n  .deadline.normal  { background: #dcfce7; color: #166534; }   /* > 7 дней */\n  .deadline.expired { background: #f1f5f9; color: #94a3b8; }   /* истёк    */\n\n  /* ── Строка тендера (цвет) ── */\n  tr.row-urgent   td:first-child { border-left: 4px solid #ef4444; }\n  tr.row-warning  td:first-child { border-left: 4px solid #f59e0b; }\n  tr.row-normal   td:first-child { border-left: 4px solid #22c55e; }\n  tr.row-expired  td:first-child { border-left: 4px solid #cbd5e1; }\n\n  /* ── Статус ИИ ── */\n  .status { padding: 2px 8px; border-radius: 4px; font-size: .78rem; font-weight: 600; }\n  .status.can_apply          { background: #dcfce7; color: #166534; }\n  .status.manual_review      { background: #fef9c3; color: #854d0e; }\n  .status.needs_clarification{ background: #ffedd5; color: #9a3412; }\n  .status.not_suitable       { background: #fee2e2; color: #991b1b; }\n  .status.new                { background: #f1f5f9; color: #64748b; }\n  .status.processing         { background: #dbeafe; color: #1d4ed8; }\n\n  /* ── Многопозиционный бейдж ── */\n  .multi-badge { background: #e0e7ff; color: #3730a3; padding: 2px 7px;\n                 border-radius: 4px; font-size: .75rem; font-weight: 600; margin-left: 6px; }\n  .partial-badge { background: #fef9c3; color: #854d0e; padding: 2px 7px;\n                   border-radius: 4px; font-size: .75rem; font-weight: 600; margin-left: 4px; }\n\n  /* ── Форма загрузки ── */\n  .upload-box { background: var(--card); border-radius: 10px; padding: 28px;\n                box-shadow: 0 1px 4px rgba(0,0,0,.06); max-width: 680px; }\n  .upload-box h2 { font-size: 1.1rem; margin-bottom: 20px; color: var(--text); }\n  .form-row { margin-bottom: 16px; }\n  .form-row label { display: block; font-size: .88rem; font-weight: 600;\n                    color: var(--sub); margin-bottom: 6px; }\n  .form-row input[type=text], .form-row input[type=url],\n  .form-row select, .form-row textarea {\n    width: 100%; padding: 9px 12px; border: 1px solid var(--border);\n    border-radius: 7px; font-size: .92rem; background: #fafafa; }\n  .form-row textarea { resize: vertical; min-height: 70px; }\n\n  /* ── Зона дропа файла ── */\n  .drop-zone { border: 2px dashed var(--border); border-radius: 10px;\n               padding: 40px 24px; text-align: center; cursor: pointer;\n               transition: all .2s; background: #fafafa; }\n  .drop-zone:hover, .drop-zone.dragover { border-color: #1a2540; background: #eff6ff; }\n  .drop-zone .icon { font-size: 2.5rem; margin-bottom: 10px; }\n  .drop-zone p { color: var(--sub); font-size: .9rem; }\n  .drop-zone p strong { color: var(--text); }\n  .drop-zone small { color: #94a3b8; font-size: .8rem; }\n  #fileInput { display: none; }\n\n  /* ── Прогресс-бар сжатия ── */\n  .compress-info { background: #f0f9ff; border: 1px solid #bae6fd; border-radius: 8px;\n                   padding: 10px 14px; margin-top: 10px; font-size: .85rem;\n                   display: none; }\n  .progress-bar { height: 6px; background: #e2e8f0; border-radius: 3px; margin-top: 8px; }\n  .progress-bar div { height: 100%; background: #1a2540; border-radius: 3px;\n                      transition: width .3s; }\n\n  /* ── Кнопки ── */\n  .btn { padding: 10px 22px; border: none; border-radius: 7px; font-size: .92rem;\n         font-weight: 600; cursor: pointer; transition: all .15s; }\n  .btn-primary { background: #1a2540; color: #fff; }\n  .btn-primary:hover { background: #243052; }\n  .btn-primary:disabled { background: #94a3b8; cursor: not-allowed; }\n  .btn-secondary { background: #f1f5f9; color: var(--text); }\n  .btn-secondary:hover { background: #e2e8f0; }\n  .btn-danger { background: #fee2e2; color: #991b1b; }\n\n  /* ── Результат анализа ── */\n  .result-card { background: var(--card); border-radius: 10px; padding: 22px 24px;\n                 box-shadow: 0 1px 4px rgba(0,0,0,.06); margin-top: 20px; display: none; }\n  .result-card h3 { font-size: 1rem; margin-bottom: 16px; }\n  .result-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n  .result-field { background: #f8fafc; border-radius: 6px; padding: 10px 14px; }\n  .result-field .k { font-size: .78rem; color: var(--sub); font-weight: 600;\n                     text-transform: uppercase; }\n  .result-field .v { font-size: .92rem; margin-top: 3px; font-weight: 500; }\n\n  /* ── Уведомление ── */\n  .toast { position: fixed; bottom: 24px; right: 24px; background: #1a2540; color: #fff;\n           padding: 14px 20px; border-radius: 10px; font-size: .9rem;\n           box-shadow: 0 4px 20px rgba(0,0,0,.2); transform: translateY(100px);\n           transition: transform .3s; z-index: 999; max-width: 340px; }\n  .toast.show { transform: translateY(0); }\n  .toast.success { background: #166534; }\n  .toast.error   { background: #991b1b; }\n\n  /* ── Безопасность ── */\n  .security-badge { position: fixed; bottom: 10px; left: 10px; background: #f1f5f9;\n                    color: #64748b; font-size: .72rem; padding: 4px 8px;\n                    border-radius: 4px; border: 1px solid var(--border); }\n\n  /* ── Детальная карточка (модальное окно) ── */\n  .modal-overlay { display: none; position: fixed; inset: 0; background: rgba(0,0,0,.4);\n                   z-index: 100; align-items: center; justify-content: center; }\n  .modal-overlay.open { display: flex; }\n  .modal { background: var(--card); border-radius: 12px; width: min(720px, 95vw);\n           max-height: 90vh; overflow-y: auto; padding: 28px;\n           box-shadow: 0 8px 40px rgba(0,0,0,.2); }\n  .modal-header { display: flex; justify-content: space-between; align-items: flex-start;\n                  margin-bottom: 20px; }\n  .modal-close { background: none; border: none; font-size: 1.4rem; cursor: pointer;\n                 color: var(--sub); line-height: 1; padding: 2px 6px; }\n  .modal-section { margin-bottom: 20px; }\n  .modal-section h4 { font-size: .85rem; color: var(--sub); font-weight: 600;\n                      text-transform: uppercase; margin-bottom: 10px;\n                      padding-bottom: 6px; border-bottom: 1px solid var(--border); }\n  .field-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }\n  .field-item { background: #f8fafc; padding: 8px 12px; border-radius: 6px; }\n  .field-item .fk { font-size: .75rem; color: var(--sub); }\n  .field-item .fv { font-size: .9rem; font-weight: 500; }\n  .reasons-list li { padding: 4px 0; font-size: .88rem; border-bottom: 1px solid #f1f5f9; }\n  .reasons-list li:last-child { border: none; }\n\n  /* ── Позиции тендера ── */\n  .positions-table { width: 100%; border-collapse: collapse; font-size: .83rem; margin-top: 10px; }\n  .positions-table th { background: #f1f5f9; padding: 7px 10px; text-align: left;\n                        color: var(--sub); font-weight: 600; }\n  .positions-table td { padding: 7px 10px; border-bottom: 1px solid #f0f4f8; }\n  .can-supply { color: #166534; font-weight: 600; }\n  .cannot-supply { color: #991b1b; }\n\n  @media (max-width: 700px) {\n    main { padding: 16px; }\n    .result-grid, .field-grid { grid-template-columns: 1fr; }\n    .stats { grid-template-columns: 1fr 1fr; }\n  }\n</style>\n</head>\n<body>\n\n<header>\n  <div style="font-size:1.5rem">⚡</div>\n  <h1>Тендерный ассистент — ТДСМ</h1>\n  <span id="currentTime"></span>\n</header>\n\n<nav>\n  <button class="active" onclick="showPanel(\'dashboard\')">📊 Дашборд</button>\n  <button onclick="showPanel(\'upload\')">📤 Загрузить тендер</button>\n  <button onclick="showPanel(\'url-analyze\')">🔗 Анализ по ссылке</button>\n  <button onclick="showPanel(\'reports\')">📋 Отчёты</button>\n  <button onclick="showPanel(\'tender-pro\')">🏪 Tender.Pro</button>\n  <button onclick="showPanel(\'tender-pro\')">🏪 Tender.Pro</button>\n</nav>\n\n<main>\n\n<!-- ═══ ДАШБОРД ═══ -->\n<div id="panel-dashboard" class="panel active">\n  <div class="stats" id="statsRow">\n    <div class="stat green"><div class="num" id="s-can">—</div><div class="lbl">Можем участвовать</div></div>\n    <div class="stat yellow"><div class="num" id="s-review">—</div><div class="lbl">На проверку</div></div>\n    <div class="stat red"><div class="num" id="s-urgent">—</div><div class="lbl">Срочно (< 3 дней)</div></div>\n    <div class="stat"><div class="num" id="s-total">—</div><div class="lbl">Всего активных</div></div>\n  </div>\n\n  <h2>Подходящие</h2>\n  <p>Закупки, прошедшие основной отбор. Статус анализа указан в таблице.</p>\n  <p id="dashboardRefresh" role="status">Загрузка…</p>\n  <div class="table-wrap">\n    <div class="table-toolbar">\n      <input type="text" id="searchInput" placeholder="🔍  Поиск по заказчику, предмету, сплаву...">\n      <select id="filterStatus" onchange="applyFilters()">\n        <option value="">Все статусы</option>\n        <option value="can_apply">✅ Можем участвовать</option>\n        <option value="manual_review">🔍 На проверку</option>\n        <option value="needs_clarification">⚠️ Нужно уточнение</option>\n        <option value="not_suitable">❌ Не подходит</option>\n      </select>\n      <select id="filterDeadline" onchange="applyFilters()">\n        <option value="">Все сроки</option>\n        <option value="urgent">🔴 Срочно (< 3 дней)</option>\n        <option value="warning">🟡 Скоро (3–7 дней)</option>\n        <option value="normal">🟢 Нормально (> 7 дней)</option>\n      </select>\n      <button class="btn btn-secondary" onclick="loadTenders()">↻ Обновить</button>\n      <button class="btn btn-primary" onclick="downloadReport()">⬇ Скачать Excel</button>\n    </div>\n    <div style="overflow-x:auto">\n      <table id="tendersTable">\n        <thead>\n          <tr>\n            <th>Заказчик</th>\n            <th>Предмет закупки</th>\n            <th>Продукт / Сплав</th>\n            <th>Масса, кг</th>\n            <th>Сумма, руб</th>\n            <th>Срок подачи</th>\n            <th>Статус ИИ</th>\n            <th>Балл</th>\n            <th>Действия</th>\n          </tr>\n        </thead>\n        <tbody id="tendersBody">\n          <tr><td colspan="9" style="text-align:center;color:var(--sub);padding:30px">\n            Загрузка тендеров...</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n  <h2 style="margin-top:28px">Выбраны вручную к закупке</h2>\n  <p>Ручной выбор сохранён независимо от результата ИИ. Ошибка анализа не является подтверждением соответствия.</p>\n  <div class="table-wrap"><table><thead><tr><th>Источник / номер</th><th>Предмет</th><th>Срок (МСК)</th><th>Анализ / результат</th><th>Действия</th></tr></thead><tbody id="manualBody"></tbody></table></div>\n  <h2 style="margin-top:28px">Требуют уточнения</h2>\n  <p id="reviewActionStatus" role="status"></p>\n  <p>Закупки из базы и до 500 последних кандидатов площадок. Неизвестный срок не подтверждает приём заявок.</p>\n  <div class="table-wrap" style="overflow-x:auto">\n    <table><thead><tr><th>Источник / номер</th><th>Предмет</th><th>Срок (МСК)</th><th>Анализ / причина</th><th>Ссылка</th></tr></thead>\n    <tbody id="reviewBody"><tr><td colspan="5">Загрузка…</td></tr></tbody></table>\n  </div>\n\n</div>\n\n<!-- ═══ ЗАГРУЗКА ФАЙЛА ═══ -->\n<div id="panel-upload" class="panel">\n  <div class="upload-box">\n    <h2>📤 Загрузить документ тендера</h2>\n\n    <div class="form-row">\n      <label>Название тендера (необязательно)</label>\n      <input type="text" id="tenderName" placeholder="Например: Закупка алюминиевого листа АД1">\n    </div>\n\n    <div class="form-row">\n      <label>Источник</label>\n      <select id="tenderSource">\n        <option value="manual_upload">Ручная загрузка</option>\n        <option value="zakupki_gov_ru">ЕИС zakupki.gov.ru</option>\n        <option value="tender_pro">Tender.Pro</option>\n        <option value="kontur_zakupki">Контур.Закупки</option>\n        <option value="commercial_etp">Коммерческая ЭТП</option>\n      </select>\n    </div>\n\n    <div class="form-row">\n      <label>Номер закупки (если известен)</label>\n      <input type="text" id="externalId" placeholder="0123456789012345">\n    </div>\n\n    <div class="form-row">\n      <label>Документ тендера</label>\n      <div class="drop-zone" id="dropZone" onclick="document.getElementById(\'fileInput\').click()">\n        <div class="icon">📄</div>\n        <p><strong>Нажмите или перетащите файл</strong></p>\n        <p>PDF, DOCX, XLSX, ZIP</p>\n        <small>До 50 МБ — без изменений &nbsp;|&nbsp; Более 50 МБ — автоматическое сжатие</small>\n      </div>\n      <input type="file" id="fileInput" accept=".pdf,.docx,.xlsx,.zip,.jpg,.jpeg,.png,.tiff">\n      <div class="compress-info" id="compressInfo">\n        <strong>🔧 Оптимизация файла</strong>\n        <div id="compressText">Подготовка...</div>\n        <div class="progress-bar"><div id="compressBar" style="width:0%"></div></div>\n      </div>\n      <div id="fileInfo" style="margin-top:8px;font-size:.85rem;color:var(--sub)"></div>\n    </div>\n\n    <div style="display:flex;gap:10px;margin-top:8px">\n      <button class="btn btn-primary" id="uploadBtn" onclick="uploadFile()" disabled>\n        🚀 Отправить на анализ\n      </button>\n      <button class="btn btn-secondary" onclick="clearUpload()">Очистить</button>\n    </div>\n\n    <div class="result-card" id="uploadResult">\n      <h3>✅ Файл отправлен на анализ</h3>\n      <p style="color:var(--sub);font-size:.9rem;margin-bottom:14px">\n        Результат придёт в Telegram и чат Битрикс24 через 1–3 минуты.\n      </p>\n      <div class="result-grid" id="uploadResultFields"></div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ АНАЛИЗ ПО ССЫЛКЕ ═══ -->\n<div id="panel-url-analyze" class="panel">\n  <div class="upload-box">\n    <h2>🔗 Анализ тендера по ссылке</h2>\n    <p style="color:var(--sub);font-size:.88rem;margin-bottom:20px">\n      Вставьте ссылку на тендер с zakupki.gov.ru, Tender.Pro или Контур.Закупки.\n      Система скачает документацию и проведёт полный анализ.\n    </p>\n\n    <div class="form-row">\n      <label>Ссылка на тендер</label>\n      <input type="url" id="tenderUrl"\n        placeholder="https://zakupki.gov.ru/epz/order/notice/ea20/view/common-info.html?regNumber=...">\n    </div>\n\n    <div class="form-row">\n      <label>Номер закупки (необязательно — извлечём из ссылки)</label>\n      <input type="text" id="urlExternalId" placeholder="0123456789012345">\n    </div>\n\n    <div class="form-row">\n      <label>Источник</label>\n      <select id="urlSource">\n        <option value="zakupki_gov_ru">ЕИС zakupki.gov.ru</option>\n        <option value="tender_pro">Tender.Pro</option>\n        <option value="kontur_zakupki">Контур.Закупки</option>\n        <option value="commercial_etp">Коммерческая ЭТП</option>\n        <option value="manual_upload">Другой источник</option>\n      </select>\n    </div>\n\n    <button class="btn btn-primary" id="analyzeUrlBtn" onclick="analyzeByUrl()">\n      🔍 Запустить анализ\n    </button>\n\n    <div class="result-card" id="urlResult">\n      <h3 id="urlResultTitle">⏳ Анализ запущен</h3>\n      <p style="color:var(--sub);font-size:.9rem;margin-bottom:14px" id="urlResultText">\n        Скачиваем документацию и запускаем анализ...\n      </p>\n      <div class="result-grid" id="urlResultFields"></div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ ОТЧЁТЫ ═══ -->\n<div id="panel-reports" class="panel">\n  <div class="upload-box" style="max-width:900px">\n    <h2>📋 Отчёты и экспорт</h2>\n\n    <div style="display:grid;gap:16px;margin-top:8px">\n      <div style="background:#f8fafc;border-radius:8px;padding:18px 20px;border:1px solid var(--border)">\n        <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px">\n          <div>\n            <div style="font-weight:600">📊 Полный отчёт по активным тендерам</div>\n            <div style="font-size:.85rem;color:var(--sub);margin-top:4px">\n              Excel-файл со всеми полями, скорингом и причинами. Отправляется также в Telegram и Битрикс24.\n            </div>\n          </div>\n          <div style="display:flex;gap:8px;flex-wrap:wrap">\n            <button class="btn btn-primary" onclick="downloadReport()">⬇ Скачать Excel</button>\n            <button class="btn btn-secondary" onclick="sendReport()">📤 Отправить в чаты</button>\n          </div>\n        </div>\n      </div>\n\n      <div style="background:#f8fafc;border-radius:8px;padding:18px 20px;border:1px solid var(--border)">\n        <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px">\n          <div>\n            <div style="font-weight:600">⏰ Расписание автоотчётов</div>\n            <div style="font-size:.85rem;color:var(--sub);margin-top:4px">\n              Ежедневно в 09:00 — краткая сводка в Telegram и Битрикс24 + Excel-файл.\n              Каждый час — обновление статуса дедлайнов.\n            </div>\n          </div>\n          <span style="background:#dcfce7;color:#166534;padding:4px 10px;border-radius:20px;font-size:.82rem;font-weight:600">\n            ✅ Активно\n          </span>\n        </div>\n      </div>\n\n      <div style="background:#f8fafc;border-radius:8px;padding:18px 20px;border:1px solid var(--border)">\n        <div style="font-weight:600;margin-bottom:8px">🔧 Ручной запуск задач</div>\n        <div style="display:flex;gap:8px;flex-wrap:wrap">\n          <button class="btn btn-secondary" onclick="triggerSource(\'zakupki_gov_ru\')">\n            ↻ Мониторинг ЕИС\n          </button>\n          <button class="btn btn-secondary" onclick="triggerSource(\'tender_pro\')">\n            ↻ Мониторинг Tender.Pro\n          </button>\n          <button class="btn btn-secondary" onclick="triggerSource(\'kontur_zakupki\')">\n            ↻ Мониторинг Контур.Закупки\n          </button>\n          <button class="btn btn-secondary" onclick="markInactive()">\n            ⏰ Обновить дедлайны\n          </button>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ TENDER.PRO ═══ -->\n<div id="panel-tender-pro" class="panel">\n  <div class="upload-box" style="max-width:900px">\n    <h2>🏪 Tender.Pro — мониторинг коммерческих тендеров</h2>\n    <p style="color:var(--sub);font-size:.88rem;margin-bottom:20px">\n      Коммерческая электронная площадка. Тендеры автоматически проверяются каждые 4 часа.<br>\n      Все релевантные тендеры попадают в общий дашборд вместе с тендерами из других источников.\n    </p>\n    <div style="background:#f0f9ff;border:1px solid #bae6fd;border-radius:8px;padding:16px 20px;margin-bottom:20px">\n      <div style="font-weight:600;margin-bottom:8px">📊 Статус интеграции</div>\n      <div id="tpStatus" style="font-size:.88rem;color:var(--sub)">Загрузка...</div>\n    </div>\n    <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:24px">\n      <button class="btn btn-primary" onclick="triggerTenderPro()">↻ Запустить проверку сейчас</button>\n      <button class="btn btn-secondary" onclick="loadTenders();\nloadTenderProStatus();showPanel(\'dashboard\',event)">📊 Перейти на дашборд</button>\n    </div>\n    <div style="background:#f8fafc;border-radius:8px;padding:18px 20px;border:1px solid var(--border)">\n      <div style="font-weight:600;margin-bottom:12px">⚙️ Параметры подключения</div>\n      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;font-size:.85rem">\n        <div class="field-item"><div class="fk">Площадка</div><div class="fv">Tender.Pro</div></div>\n        <div class="field-item"><div class="fk">Тип тендеров</div><div class="fv">Коммерческие (open_only)</div></div>\n        <div class="field-item"><div class="fk">Расписание</div><div class="fv">Каждые 4 часа</div></div>\n        <div class="field-item"><div class="fk">Фильтр</div><div class="fv">По ключевым словам алюминия</div></div>\n        <div class="field-item"><div class="fk">API метод</div><div class="fv">_info.tenderlist_by_set</div></div>\n        <div class="field-item"><div class="fk">Статус ключа</div><div class="fv" style="color:#166534">✅ Активен</div></div>\n      </div>\n    </div>\n  </div>\n</div>\n\n\n<!-- ═══ TENDER.PRO ═══ -->\n<div id="panel-tender-pro" class="panel">\n  <div class="upload-box" style="max-width:900px">\n    <h2>🏪 Tender.Pro — коммерческие тендеры</h2>\n    <p style="color:var(--sub);font-size:.88rem;margin-bottom:20px">\n      Коммерческая площадка. Тендеры проверяются каждые 4 часа автоматически.<br>\n      Все релевантные тендеры попадают в общий дашборд вместе с тендерами других источников.\n    </p>\n\n    <div style="background:#f0f9ff;border:1px solid #bae6fd;border-radius:8px;padding:16px 20px;margin-bottom:20px">\n      <div style="font-weight:600;margin-bottom:8px">📊 Статус интеграции</div>\n      <div id="tpStatus" style="font-size:.88rem;color:var(--sub)">Загрузка...</div>\n    </div>\n\n    <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:24px">\n      <button class="btn btn-primary" onclick="triggerTenderPro()">↻ Запустить проверку сейчас</button>\n      <button class="btn btn-secondary" onclick="loadTenders();\nloadTenderProStatus();showPanel2(\'dashboard\')">📊 Перейти на дашборд</button>\n    </div>\n\n    <div style="background:#f8fafc;border-radius:8px;padding:18px 20px;border:1px solid var(--border)">\n      <div style="font-weight:600;margin-bottom:12px">⚙️ Параметры подключения</div>\n      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;font-size:.85rem">\n        <div class="field-item"><div class="fk">Площадка</div><div class="fv">Tender.Pro</div></div>\n        <div class="field-item"><div class="fk">Тип тендеров</div><div class="fv">Коммерческие (open_only)</div></div>\n        <div class="field-item"><div class="fk">Расписание</div><div class="fv">Каждые 4 часа</div></div>\n        <div class="field-item"><div class="fk">Фильтр</div><div class="fv">Ключевые слова алюминия</div></div>\n        <div class="field-item"><div class="fk">API метод</div><div class="fv">_info.tenderlist_by_set</div></div>\n        <div class="field-item"><div class="fk">Статус ключа</div><div class="fv" style="color:#166534">✅ Активен</div></div>\n      </div>\n    </div>\n\n    <div style="margin-top:20px;background:#f8fafc;border-radius:8px;padding:18px 20px;border:1px solid var(--border)">\n      <div style="font-weight:600;margin-bottom:12px">📋 Тендеры Tender.Pro в дашборде</div>\n      <div id="tpList" style="font-size:.88rem;color:var(--sub)">Загрузка...</div>\n    </div>\n  </div>\n</div>\n\n</main>\n\n<!-- ═══ МОДАЛЬНОЕ ОКНО ТЕНДЕРА ═══ -->\n<div class="modal-overlay" id="tenderModal" onclick="closeModal(event)">\n  <div class="modal" id="modalContent">\n    <div class="modal-header">\n      <div>\n        <h2 style="font-size:1.1rem" id="modalTitle">Карточка тендера</h2>\n        <div style="font-size:.85rem;color:var(--sub);margin-top:4px" id="modalSubtitle"></div>\n      </div>\n      <button class="modal-close" onclick="document.getElementById(\'tenderModal\').classList.remove(\'open\')">✕</button>\n    </div>\n    <div id="modalBody"></div>\n  </div>\n</div>\n\n<!-- Уведомление -->\n<div class="toast" id="toast"></div>\n\n<!-- Значок ФЗ-152 -->\n<div class="security-badge">🔒 152-ФЗ</div>\n\n<script>\n// ══════════════════════════════════════════════════\n// Утилиты\n// ══════════════════════════════════════════════════\nfunction showPanel(name) {\n  document.querySelectorAll(\'.panel\').forEach(p => p.classList.remove(\'active\'));\n  document.querySelectorAll(\'nav button\').forEach(b => b.classList.remove(\'active\'));\n  document.getElementById(\'panel-\' + name).classList.add(\'active\');\n  event.currentTarget.classList.add(\'active\');\n  if (name === \'dashboard\') loadTenders();\nloadTenderProStatus();\n}\n\nfunction toast(msg, type=\'\') {\n  const t = document.getElementById(\'toast\');\n  t.textContent = msg; t.className = \'toast show \' + type;\n  setTimeout(() => t.classList.remove(\'show\'), 4000);\n}\n\n// Обновляем часы в шапке\nfunction updateTime() {\n  document.getElementById(\'currentTime\').textContent =\n    new Date().toLocaleString(\'ru-RU\', {dateStyle:\'medium\', timeStyle:\'short\'});\n}\nupdateTime(); setInterval(updateTime, 30000);\n\n// ══════════════════════════════════════════════════\n// Окраска по дедлайну\n// ══════════════════════════════════════════════════\nfunction deadlineClass(deadlineStr) {\n  if (!deadlineStr) return \'expired\';\n  const parts = deadlineStr.match(/(\\d{2})\\.(\\d{2})\\.(\\d{4})/);\n  if (!parts) return \'expired\';\n  const d = new Date(parts[3], parts[2]-1, parts[1]);\n  const now = new Date();\n  const diff = (d - now) / 86400000;\n  if (diff < 0)   return \'expired\';\n  if (diff < 3)   return \'urgent\';\n  if (diff < 7)   return \'warning\';\n  return \'normal\';\n}\n\nfunction deadlineLabel(deadlineStr, cls) {\n  const labels = {\n    urgent: \'🔴 Срочно\',\n    warning: \'🟡 Скоро\',\n    normal: \'🟢\',\n    expired: \'⬜ Истёк\'\n  };\n  const prefix = labels[cls] || \'\';\n  return `<span class="deadline ${cls}">${prefix} ${deadlineStr || \'не указан\'}</span>`;\n}\n\nfunction statusBadge(status) {\n  const labels = {\n    can_apply: \'Можем участвовать\',\n    manual_review: \'Участие требует уточнения\',\n    needs_clarification: \'Нужно уточнение\',\n    not_suitable: \'Не подходит\',\n    new: \'Новый\',\n    processing: \'Обработка...\',\n  };\n  return `<span class="status ${status}">${labels[status] || status}</span>`;\n}\n\n// ══════════════════════════════════════════════════\n// Загрузка и отображение тендеров\n// ══════════════════════════════════════════════════\nlet allTenders = [];\n\nlet dashboardLoading = false;\nasync function loadTenders() {\n  if (dashboardLoading) return;\n  dashboardLoading = true;\n  const controller = new AbortController();\n  const timer = setTimeout(() => controller.abort(), 25000);\n  try {\n    const responses = await Promise.all([\'/tenders/dashboard\', \'/tenders/review\', \'/tenders/manual-analysis\'].map(url =>\n      fetch(url, {signal: controller.signal, cache: \'no-store\'})));\n    if (responses.some(r => !r.ok)) throw new Error(\'HTTP\');\n    const [main, review, manual] = await Promise.all(responses.map(r => r.json()));\n    if (!Array.isArray(main.tenders) || !Array.isArray(review.tenders)) throw new Error(\'Data\');\n    allTenders = main.tenders;\n    const mainKeys = new Set(allTenders.map(t => t.source + \':\' + (t.external_id || t.id)));\n    const manualRows = manual.tenders || [];\n    const manualKeys = new Set(manualRows.map(t => t.source + \':\' + t.external_id));\n    const reviewRows = review.tenders.filter(t => !mainKeys.has(t.source + \':\' + t.external_id) && !manualKeys.has(t.source + \':\' + t.external_id));\n    renderManual(manualRows);\n    updateStats(allTenders);\n    document.getElementById(\'s-review\').textContent = reviewRows.length;\n    document.getElementById(\'s-total\').textContent = allTenders.length + reviewRows.length;\n    applyFilters();\n    renderReview(reviewRows);\n    document.getElementById(\'dashboardRefresh\').textContent = \'Обновлено: \' + new Date().toLocaleTimeString(\'ru-RU\') + \'. Обновление раз в минуту.\';\n  } catch(e) {\n    document.getElementById(\'dashboardRefresh\').textContent = \'Не удалось обновить данные. Показанные ранее данные могут быть устаревшими. Нажмите «Обновить».\';\n  } finally { clearTimeout(timer); dashboardLoading = false; }\n}\nasync function analyzeReview(row, button) {\n  button.disabled = true; button.textContent = \'Постановка в очередь…\';\n  try {\n    const response = await fetch(\'/tenders/manual-analysis\', {method:\'POST\',\n      headers:{\'Content-Type\':\'application/json\',\'X-Review-Action\':\'manual\'},\n      body:JSON.stringify({source:row.source,external_id:String(row.external_id)})});\n    if (!response.ok) { const error = await response.json(); throw new Error(error.detail || \'Ошибка запуска\'); }\n    document.getElementById(\'reviewActionStatus\').textContent = \'Ручной выбор сохранён, анализ поставлен в очередь.\';\n    await loadTenders();\n  } catch(error) { button.disabled=false; button.textContent=\'Повторить запуск\'; document.getElementById(\'reviewActionStatus\').textContent=String(error.message); }\n}\nfunction renderManual(rows) {\n  const body=document.getElementById(\'manualBody\'); body.replaceChildren();\n  for (const row of rows) {\n    const tr=document.createElement(\'tr\');\n    const state=({queued:\'В очереди\',running:\'Анализируется\',done:\'Анализ завершён\',error:\'Ошибка анализа\'})[row.state] || row.state;\n    const text=\'Выбрана вручную · \'+state+(row.error ? \': \'+row.error : \'\')+(row.score != null ? \'. Последний рейтинг: \'+row.score : \'\')+(row.ai_decision ? \'. Вывод ИИ: \'+row.ai_decision : \'\');\n    for (const value of [row.source+\' / \'+row.external_id,row.title,new Date(row.submission_deadline).toLocaleString(\'ru-RU\',{timeZone:\'Europe/Moscow\'}),text]) {\n      const td=document.createElement(\'td\');td.textContent=value;tr.append(td);\n    }\n    const td=document.createElement(\'td\');\n    try { const url=new URL(row.source_url);if([\'https:\',\'http:\'].includes(url.protocol)){const a=document.createElement(\'a\');a.href=url.href;a.target=\'_blank\';a.rel=\'noopener noreferrer\';a.textContent=\'Открыть\';td.append(a);}}catch(e){}\n    const button=document.createElement(\'button\');button.className=\'btn btn-secondary\';button.textContent=row.state===\'error\'?\'Повторить анализ\':\'Анализировать повторно\';button.disabled=[\'queued\',\'running\'].includes(row.state);button.onclick=()=>analyzeReview(row,button);td.append(button);\n    const remove=document.createElement(\'button\');remove.textContent=\'Не подходит — убрать\';remove.onclick=()=>dismissReview(row,remove);td.append(remove);\n    tr.append(td);body.append(tr);\n  }\n  if(!rows.length){const tr=document.createElement(\'tr\');const td=document.createElement(\'td\');td.colSpan=5;td.textContent=\'Нет закупок, выбранных вручную\';tr.append(td);body.append(tr);}\n}\nasync function dismissReview(row, button) {\n  if (!confirm(\'Убрать закупку \' + row.external_id + \' из списка проверки? История сохранится.\')) return;\n  button.disabled = true;\n  const status = document.getElementById(\'reviewActionStatus\');\n  try {\n    await saveReviewDismissal(row, true);\n    status.replaceChildren(document.createTextNode(\'Закупка \' + row.external_id + \' убрана. \'));\n    const undo = document.createElement(\'button\'); undo.textContent=\'Отменить\';\n    undo.onclick = async () => {\n      undo.disabled=true;\n      try { await saveReviewDismissal(row, false); status.textContent=\'Исключение отменено\'; await loadTenders(); }\n      catch(e) { undo.disabled=false; alert(\'Не удалось восстановить запись\'); }\n    };\n    status.append(undo);\n    await loadTenders();\n  } catch(e) { status.textContent=\'Не удалось убрать запись. Попробуйте снова.\'; button.disabled=false; }\n}\nasync function saveReviewDismissal(row, dismissed) {\n  const response = await fetch(\'/tenders/review/dismiss\', {method:\'POST\',\n    headers:{\'Content-Type\':\'application/json\',\'X-Review-Action\':\'manual\'},\n    body:JSON.stringify({source:row.source, external_id:String(row.external_id), dismissed})});\n  if (!response.ok) throw new Error(\'Save failed\');\n}\nfunction renderReview(rows) {\n  const body = document.getElementById(\'reviewBody\');\n  body.replaceChildren();\n  if (!rows.length) {\n    const td = document.createElement(\'td\'); td.colSpan = 5; td.textContent = \'Закупок для уточнения нет\';\n    const tr = document.createElement(\'tr\'); tr.append(td); body.append(tr); return;\n  }\n  for (const row of rows) {\n    const tr = document.createElement(\'tr\');\n    const deadline = row.submission_deadline ? new Date(row.submission_deadline).toLocaleString(\'ru-RU\', {timeZone:\'Europe/Moscow\'}) : \'Срок неизвестен\';\n    for (const value of [row.source + \' / \' + row.external_id, row.title, deadline,\n      (row.analysis_done ? \'Анализ выполнен. \' : \'Полный анализ не подтверждён. \') + (row.reason || \'Требуется уточнение\')]) {\n      const td = document.createElement(\'td\'); td.textContent = value || \'—\'; tr.append(td);\n    }\n    const td = document.createElement(\'td\');\n    try {\n      const url = new URL(row.source_url);\n      if ([\'http:\', \'https:\'].includes(url.protocol)) {\n        const a = document.createElement(\'a\'); a.href=url.href; a.target=\'_blank\'; a.rel=\'noopener noreferrer\'; a.textContent=\'Открыть\'; td.append(a);\n      }\n    } catch(e) {}\n    const analyze = document.createElement(\'button\');analyze.className=\'btn btn-primary\';analyze.textContent=\'Подходит к закупке — анализировать\';analyze.onclick=()=>analyzeReview(row,analyze);td.append(document.createElement(\'br\'),analyze);\n    const button = document.createElement(\'button\');\n    button.className = \'btn btn-secondary\'; button.textContent = \'Не подходит — убрать\';\n    button.onclick = () => dismissReview(row, button);\n    td.append(document.createElement(\'br\'), button);\n    tr.append(td); body.append(tr);\n  }\n}\nsetInterval(() => {\n  if (!document.hidden && document.getElementById(\'panel-dashboard\').classList.contains(\'active\')) loadTenders();\n}, 60000);\n\nfunction updateStats(tenders) {\ndocument.getElementById(\'s-total\').textContent =\n    tenders.length;\n\ndocument.getElementById(\'s-can\').textContent =\n    tenders.filter(\n     t => t.status === \'can_apply\'\n    ).length;\n\ndocument.getElementById(\'s-review\').textContent =\n    tenders.filter(\n     t =>\n        [\'manual_review\',\'needs_clarification\']\n        .includes(t.status)\n        || t.analysis_done === false\n    ).length;\n\ndocument.getElementById(\'s-urgent\').textContent =\n    tenders.filter(\n     t =>\n        deadlineClass(\n         t.submission_deadline\n        ) === \'urgent\'\n    ).length;\n}\n\nfunction renderTable(tenders) {\nconst tbody = document.getElementById(\'tendersBody\');\n\nif (!tenders.length) {\n    tbody.innerHTML =\n     \'<tr><td colspan="9" style="text-align:center;color:var(--sub);padding:30px">Активных тендеров нет</td></tr>\';\n    return;\n}\n\ntbody.innerHTML = tenders.map(t => {\n    const dc = deadlineClass(t.submission_deadline);\n\n    const positionsCount = Number(t.positions_count || 0);\n\n    const positionBadge = positionsCount > 1\n     ? `<span class="multi-badge">Позиций: ${positionsCount}</span>`\n     : \'\';\n\n    let weightText = \'—\';\n\n    if (t.relevant_weight_kg !== null &&\n        t.relevant_weight_kg !== undefined) {\n     weightText =\n        Number(t.relevant_weight_kg).toLocaleString(\'ru\') + \' кг\';\n    } else if (t.weight_status === \'unknown\') {\n     weightText = \'Уточнить\';\n    }\n\n    if (t.weight_status === \'mass_unknown_pieces_ok\') weightText = \'Масса не указана\';\n    let weightBadge = \'\';\n\n    if (t.weight_status === \'mass_unknown_pieces_ok\') {\n     weightBadge = \'<span class="multi-badge">≥ 200 шт. в одной позиции</span>\';\n    } else if (t.weight_status === \'below_minimum\') {\n     weightBadge =\n        \'<span class="partial-badge">< 500 кг</span>\';\n    } else if (t.weight_status === \'ok\') {\n     weightBadge =\n        \'<span class="multi-badge">≥ 500 кг</span>\';\n    } else if (t.weight_status === \'unknown\') {\n     weightBadge =\n        \'<span class="partial-badge">Вес не определён</span>\';\n    }\n\n    const priorityLabel = ({high:\'Приоритет: от 1 млн ₽\',normal:\'От 500 тыс. ₽\',low:\'Менее 500 тыс. ₽\',price_unknown:\'Цена не указана\',currency_review:\'Проверить валюту\'})[t.price_priority] || \'\';\n    const analysisText =\n     t.analysis_state || \'Ожидает анализа\';\n\n    return `\n     <tr class="row-${dc}"\n         onclick="openTenderModal(\'${t.external_id}\')">\n\n        <td>\n         <strong>${sanitize(\n            t.customer_name || t.external_id\n         )}</strong>\n         <div style="font-size:.75rem;color:var(--sub);margin-top:4px">\n            ${sanitize(t.source || \'\')}\n         </div>\n        </td>\n\n        <td>\n         ${sanitize(\n            (t.title || \'\').substring(0,70)\n         )}\n         ${(t.title || \'\').length > 70 ? \'…\' : \'\'}\n         <div style="margin-top:5px">\n            ${positionBadge} <span class="multi-badge">${sanitize(priorityLabel)}</span>\n            <div>${sanitize(t.participation_description || \'\')}</div>\n         </div>\n        </td>\n\n        <td>\n         ${positionsCount\n            ? `${positionsCount} поз.`\n            : \'—\'}\n        </td>\n\n        <td>\n         <strong>${weightText}</strong><div style="font-size:.75rem">Одна подходящая позиция</div>\n         <div style="margin-top:5px">\n            ${weightBadge}\n         </div>\n        </td>\n\n        <td>\n         ${t.amount\n            ? Number(t.amount).toLocaleString(\'ru\')\n            : \'—\'}\n        </td>\n\n        <td>\n         ${deadlineLabel(\n            t.submission_deadline,\n            dc\n         )}\n        </td>\n\n        <td>\n         <div>${statusBadge(t.status)}</div>\n         <div style="font-size:.75rem;color:var(--sub);margin-top:4px">\n            ${sanitize(analysisText)}\n         </div>\n        </td>\n\n        <td>\n         <strong>${t.score || 0}</strong>\n        </td>\n\n        <td>\n         <button\n            class="btn btn-secondary"\n            style="padding:5px 10px;font-size:.8rem"\n            onclick="event.stopPropagation();openTenderModal(\'${t.external_id}\')">\n            Открыть\n         </button>\n        </td>\n\n     </tr>\n    `;\n}).join(\'\');\n}\n\nfunction sanitize(str) {\n  if (!str) return \'\';\n  return String(str).replace(/&/g,\'&amp;\').replace(/</g,\'&lt;\').replace(/>/g,\'&gt;\');\n}\n\nfunction applyFilters() {\n  const q = document.getElementById(\'searchInput\').value.toLowerCase();\n  const st = document.getElementById(\'filterStatus\').value;\n  const dl = document.getElementById(\'filterDeadline\').value;\n\n  const filtered = allTenders.filter(t => {\n    const text = [t.customer_name, t.title, t.alloy, t.product_type, t.region].join(\' \').toLowerCase();\n    if (q && !text.includes(q)) return false;\n    if (st && t.status !== st) return false;\n    if (dl && deadlineClass(t.submission_deadline) !== dl) return false;\n    return true;\n  });\n  renderTable(filtered);\n}\n\ndocument.getElementById(\'searchInput\').addEventListener(\'input\', applyFilters);\n\n// ══════════════════════════════════════════════════\n// Модальное окно тендера\n// ══════════════════════════════════════════════════\nfunction openTenderModal(externalId) {\n  const t = allTenders.find(x => x.external_id === externalId);\n  if (!t) return;\n\n  document.getElementById(\'modalTitle\').textContent = t.title.substring(0,80);\n  document.getElementById(\'modalSubtitle\').textContent =\n    `${t.customer_name || \'\'} · ${t.source} · Балл: ${t.score || 0}`;\n\n  const dc = deadlineClass(t.submission_deadline);\n  const isMulti = t.positions && t.positions.length > 1;\n\n  let positionsHtml = \'\';\n\nif (t.positions && t.positions.length) {\n    const matchedPositions = t.positions.filter(\n     p => p.pre_filter_relevant === true\n    );\n\n    const otherPositions = t.positions.filter(\n     p => p.pre_filter_relevant !== true\n    );\n\n    const renderPositionRow = (p, matched) => {\n     const products = (\n        p.pre_filter_products || []\n     ).join(\', \');\n\n     const alloys = (\n        p.pre_filter_alloys || []\n     ).join(\', \');\n\n     const tempers = (\n        p.pre_filter_tempers || []\n     ).join(\', \');\n\n     const quantity = (\n        p.quantity !== null &&\n        p.quantity !== undefined &&\n        p.quantity !== \'\'\n     )\n        ? `${p.quantity} ${p.unit || \'\'}`\n        : \'—\';\n\n     const mass = (\n        p.mass_kg !== null &&\n        p.mass_kg !== undefined\n     )\n        ? Number(\n            p.mass_kg\n         ).toLocaleString(\'ru\') + \' кг\'\n        : \'—\';\n\n     return `\n        <tr style="${\n         matched\n            ? \'background:#f0fdf4\'\n            : \'\'\n        }">\n         <td>\n            ${p.position_number || \'—\'}\n         </td>\n\n         <td>\n            <strong>\n             ${sanitize(\n                p.name ||\n                p.name_product ||\n                \'—\'\n             )}\n            </strong>\n\n            ${\n             matched\n                ? `\n                 <div\n                    style="\n                     color:#166534;\n                     font-weight:600;\n                     font-size:.78rem;\n                     margin-top:5px\n                    "\n                 >\n                    ✓ Подходит по первичному фильтру\n                 </div>\n                `\n                : \'\'\n            }\n         </td>\n\n         <td>\n            ${sanitize(products || \'—\')}\n         </td>\n\n         <td>\n            ${\n             alloys\n                ? `<code>${sanitize(alloys)}</code>`\n                : \'—\'\n            }\n         </td>\n\n         <td>\n            ${sanitize(tempers || \'—\')}\n         </td>\n\n         <td>\n            ${quantity}\n         </td>\n\n         <td>\n            ${mass}\n         </td>\n\n         <td>\n            <strong\n             style="${\n                matched\n                 ? \'color:#166534\'\n                 : \'color:var(--sub)\'\n             }"\n            >\n             ${p.pre_filter_score || 0}\n            </strong>\n         </td>\n        </tr>\n     `;\n    };\n\n    let matchedHtml = \'\';\n\n    if (matchedPositions.length) {\n     matchedHtml = `\n        <div class="modal-section">\n         <h4>\n            Подходящие позиции:\n            ${matchedPositions.length}\n            из\n            ${t.positions.length}\n         </h4>\n\n         <table class="positions-table">\n            <thead>\n             <tr>\n                <th>#</th>\n                <th>Наименование</th>\n                <th>Продукт</th>\n                <th>Сплав</th>\n                <th>Состояние</th>\n                <th>Количество</th>\n                <th>Масса</th>\n                <th>Score</th>\n             </tr>\n            </thead>\n\n            <tbody>\n             ${matchedPositions.map(\n                p => renderPositionRow(\n                 p,\n                 true\n                )\n             ).join(\'\')}\n            </tbody>\n         </table>\n        </div>\n     `;\n    }\n\n    let otherHtml = \'\';\n\n    if (otherPositions.length) {\n     otherHtml = `\n        <details\n         class="modal-section"\n         style="margin-top:16px"\n        >\n         <summary\n            style="\n             cursor:pointer;\n             font-weight:600\n            "\n         >\n            Прочие позиции закупки:\n            ${otherPositions.length}\n         </summary>\n\n         <div style="margin-top:12px">\n            <table class="positions-table">\n             <thead>\n                <tr>\n                 <th>#</th>\n                 <th>Наименование</th>\n                 <th>Продукт</th>\n                 <th>Сплав</th>\n                 <th>Состояние</th>\n                 <th>Количество</th>\n                 <th>Масса</th>\n                 <th>Score</th>\n                </tr>\n             </thead>\n\n             <tbody>\n                ${otherPositions.map(\n                 p => renderPositionRow(\n                    p,\n                    false\n                 )\n                ).join(\'\')}\n             </tbody>\n            </table>\n         </div>\n        </details>\n     `;\n    }\n\n    positionsHtml =\n     matchedHtml +\n     otherHtml;\n}\n\n const reasons = (t.reasons || []).map(r =>\n    `<li>• ${sanitize(r)}</li>`).join(\'\');\n  const risks = (t.risks || []).map(r =>\n    `<li style="color:#991b1b">⚠ ${sanitize(r)}</li>`).join(\'\');\n\n  document.getElementById(\'modalBody\').innerHTML = `\n    <div class="modal-section">\n      <h4>Статус и сроки</h4>\n      <div class="field-grid">\n        <div class="field-item"><div class="fk">Решение ИИ</div>\n          <div class="fv">${statusBadge(t.status)}</div></div>\n        <div class="field-item"><div class="fk">Балл</div>\n          <div class="fv"><strong>${t.score || 0}</strong>/100</div></div>\n        <div class="field-item"><div class="fk">Срок подачи</div>\n          <div class="fv">${deadlineLabel(t.submission_deadline, dc)}</div></div>\n        <div class="field-item"><div class="fk">Регион</div>\n          <div class="fv">${sanitize(t.region || \'—\')}</div></div>\n      </div>\n    </div>\n\n    <div class="modal-section">\n        <h4>Первичный фильтр</h4>\n\n        <div class="field-grid">\n\n         <div class="field-item">\n            <div class="fk">Подходящих позиций</div>\n            <div class="fv">\n             <strong>\n                ${t.matched_count || 0}\n                из\n                ${t.positions_count || 0}\n             </strong>\n            </div>\n         </div>\n\n         <div class="field-item">\n            <div class="fk">Релевантная масса</div>\n            <div class="fv">\n             <strong>\n                ${\n                 t.relevant_weight_kg !== null &&\n                 t.relevant_weight_kg !== undefined\n                    ? Number(\n                        t.relevant_weight_kg\n                     ).toLocaleString(\'ru\') + \' кг\'\n                    : \'Уточнить\'\n                }\n             </strong>\n            </div>\n         </div>\n\n         <div class="field-item">\n            <div class="fk">Весовой фильтр</div>\n            <div class="fv">\n             ${\n                t.weight_status === \'ok\'\n                 ? \'✅ От 500 кг\'\n                 : t.weight_status === \'below_minimum\'\n                    ? \'❌ Менее 500 кг\'\n                    : t.weight_status === \'unknown\'\n                     ? \'⚠ Требуется расчёт\'\n                     : \'—\'\n             }\n            </div>\n         </div>\n\n         <div class="field-item">\n            <div class="fk">Статус анализа</div>\n            <div class="fv">\n             ${sanitize(\n                t.analysis_state ||\n                \'Ожидает анализа\'\n             )}\n            </div>\n         </div>\n\n        </div>\n     </div>\n\n     <div class="modal-section">\n      <h4>Договор и поставка</h4>\n      <div class="field-grid">\n        <div class="field-item"><div class="fk">НМЦК</div>\n          <div class="fv">${t.amount ? Number(t.amount).toLocaleString(\'ru\') + \' ₽\' : \'—\'}</div></div>\n        <div class="field-item"><div class="fk">Место поставки</div>\n          <div class="fv">${sanitize(t.delivery_place || \'—\')}</div></div>\n        <div class="field-item"><div class="fk">Срок поставки</div>\n          <div class="fv">${sanitize(t.delivery_term || \'—\')}</div></div>\n        <div class="field-item"><div class="fk">Условия оплаты</div>\n          <div class="fv">${sanitize(t.payment_terms || \'—\')}</div></div>\n      </div>\n    </div>\n\n    ${positionsHtml}\n\n    <div class="modal-section">\n      <h4>Причины оценки</h4>\n      <ul class="reasons-list">${reasons || \'<li style="color:var(--sub)">Нет данных</li>\'}</ul>\n    </div>\n\n    ${risks ? `<div class="modal-section">\n      <h4>Критические риски</h4>\n      <ul class="reasons-list">${risks}</ul>\n    </div>` : \'\'}\n\n    ${t.source_url ? `<div style="margin-top:16px">\n      <a href="${sanitize(t.source_url)}" target="_blank" class="btn btn-secondary"\n         rel="noopener noreferrer" onclick="event.stopPropagation()">\n        🔗 Открыть на площадке\n      </a>\n    </div>` : \'\'}\n  `;\n\n  document.getElementById(\'tenderModal\').classList.add(\'open\');\n}\n\nfunction closeModal(e) {\n  if (e.target === document.getElementById(\'tenderModal\'))\n    document.getElementById(\'tenderModal\').classList.remove(\'open\');\n}\n\n// ══════════════════════════════════════════════════\n// Загрузка файла с проверкой размера и сжатием\n// ══════════════════════════════════════════════════\nconst MAX_SIZE_MB = 50;\nlet selectedFile = null;\n\ndocument.getElementById(\'fileInput\').addEventListener(\'change\', handleFileSelect);\n\n// Drag & drop\nconst dropZone = document.getElementById(\'dropZone\');\ndropZone.addEventListener(\'dragover\', e => { e.preventDefault(); dropZone.classList.add(\'dragover\'); });\ndropZone.addEventListener(\'dragleave\', () => dropZone.classList.remove(\'dragover\'));\ndropZone.addEventListener(\'drop\', e => {\n  e.preventDefault(); dropZone.classList.remove(\'dragover\');\n  if (e.dataTransfer.files[0]) {\n    document.getElementById(\'fileInput\').files = e.dataTransfer.files;\n    handleFileSelect({ target: document.getElementById(\'fileInput\') });\n  }\n});\n\nasync function handleFileSelect(e) {\n  const file = e.target.files[0];\n  if (!file) return;\n\n  const sizeMb = file.size / 1024 / 1024;\n  const info = document.getElementById(\'fileInfo\');\n  const compressInfo = document.getElementById(\'compressInfo\');\n\n  if (sizeMb > 200) {\n    info.innerHTML = `<span style="color:#991b1b">❌ Файл слишком большой (${sizeMb.toFixed(1)} МБ). Максимум 200 МБ.</span>`;\n    document.getElementById(\'uploadBtn\').disabled = true;\n    selectedFile = null;\n    return;\n  }\n\n  if (sizeMb > MAX_SIZE_MB) {\n    // Показываем прогресс "оптимизации" (на стороне сервера будет настоящее сжатие)\n    compressInfo.style.display = \'block\';\n    document.getElementById(\'compressText\').textContent =\n      `Файл ${sizeMb.toFixed(1)} МБ — будет оптимизирован перед отправкой`;\n    let p = 0;\n    const bar = document.getElementById(\'compressBar\');\n    const iv = setInterval(() => {\n      p = Math.min(p + 15, 90);\n      bar.style.width = p + \'%\';\n    }, 200);\n    // Имитируем подготовку — реальное сжатие на сервере\n    await new Promise(r => setTimeout(r, 1500));\n    clearInterval(iv);\n    bar.style.width = \'100%\';\n    document.getElementById(\'compressText\').textContent =\n      `✅ Готово к отправке. Сервер сожмёт файл перед анализом.`;\n    selectedFile = file;\n  } else {\n    compressInfo.style.display = \'none\';\n    selectedFile = file;\n  }\n\n  info.innerHTML = `📎 <strong>${file.name}</strong> — ${sizeMb.toFixed(2)} МБ`;\n  document.getElementById(\'uploadBtn\').disabled = false;\n}\n\nasync function uploadFile() {\n  if (!selectedFile) { toast(\'Выберите файл\', \'error\'); return; }\n\n  const btn = document.getElementById(\'uploadBtn\');\n  btn.disabled = true; btn.textContent = \'⏳ Загрузка...\';\n\n  const fd = new FormData();\n  fd.append(\'file\', selectedFile);\n  fd.append(\'tender_name\', document.getElementById(\'tenderName\').value);\n  fd.append(\'source\', document.getElementById(\'tenderSource\').value);\n  fd.append(\'external_id\', document.getElementById(\'externalId\').value);\n\n  try {\n    const res = await fetch(\'/upload/tender\', { method: \'POST\', body: fd });\n    const data = await res.json();\n\n    if (res.ok) {\n      document.getElementById(\'uploadResult\').style.display = \'block\';\n      document.getElementById(\'uploadResultFields\').innerHTML = `\n        <div class="result-field"><div class="k">ID задачи</div>\n          <div class="v">${data.task_id}</div></div>\n        <div class="result-field"><div class="k">Файл</div>\n          <div class="v">${data.filename}</div></div>\n        <div class="result-field"><div class="k">Размер</div>\n          <div class="v">${data.size_kb} КБ</div></div>\n        <div class="result-field"><div class="k">Статус</div>\n          <div class="v">В очереди на обработку</div></div>\n      `;\n      toast(\'✅ Файл отправлен на анализ!\', \'success\');\n    } else {\n      toast(\'❌ \' + (data.detail || \'Ошибка загрузки\'), \'error\');\n    }\n  } catch(e) {\n    toast(\'❌ Ошибка соединения с сервером\', \'error\');\n  }\n\n  btn.disabled = false; btn.textContent = \'🚀 Отправить на анализ\';\n}\n\nfunction clearUpload() {\n  selectedFile = null;\n  document.getElementById(\'fileInput\').value = \'\';\n  document.getElementById(\'fileInfo\').textContent = \'\';\n  document.getElementById(\'compressInfo\').style.display = \'none\';\n  document.getElementById(\'uploadResult\').style.display = \'none\';\n  document.getElementById(\'uploadBtn\').disabled = true;\n  document.getElementById(\'tenderName\').value = \'\';\n  document.getElementById(\'externalId\').value = \'\';\n}\n\n// ══════════════════════════════════════════════════\n// Анализ по URL\n// ══════════════════════════════════════════════════\nasync function analyzeByUrl() {\n  const url = document.getElementById(\'tenderUrl\').value.trim();\n  if (!url) { toast(\'Введите ссылку на тендер\', \'error\'); return; }\n\n  const btn = document.getElementById(\'analyzeUrlBtn\');\n  btn.disabled = true; btn.textContent = \'⏳ Запускаем анализ...\';\n\n  // Извлекаем номер закупки из URL если не введён вручную\n  let extId = document.getElementById(\'urlExternalId\').value.trim();\n  if (!extId) {\n    const match = url.match(/regNumber=(\\d+)|\\/(\\d{16,})/);\n    if (match) extId = match[1] || match[2];\n  }\n\n  try {\n    const res = await fetch(\'/tenders/analyze-url\', {\n      method: \'POST\',\n      headers: { \'Content-Type\': \'application/json\' },\n      body: JSON.stringify({\n        url: url,\n        external_id: extId || \'\',\n        source: document.getElementById(\'urlSource\').value,\n      })\n    });\n    const data = await res.json();\n\n    const resultCard = document.getElementById(\'urlResult\');\n    resultCard.style.display = \'block\';\n\n    if (res.ok) {\n      document.getElementById(\'urlResultTitle\').textContent = \'✅ Анализ запущен\';\n      document.getElementById(\'urlResultText\').textContent =\n        \'Скачиваем документацию и запускаем полный анализ. Результат придёт в Telegram и Битрикс24.\';\n      document.getElementById(\'urlResultFields\').innerHTML = `\n        <div class="result-field"><div class="k">ID задачи</div>\n          <div class="v">${data.task_id || \'—\'}</div></div>\n        <div class="result-field"><div class="k">Номер закупки</div>\n          <div class="v">${data.external_id || extId || \'—\'}</div></div>\n      `;\n      toast(\'🔍 Анализ запущен!\', \'success\');\n    } else {\n      document.getElementById(\'urlResultTitle\').textContent = \'❌ Ошибка\';\n      document.getElementById(\'urlResultText\').textContent = data.detail || \'Не удалось запустить анализ\';\n      toast(\'❌ Ошибка: \' + (data.detail || \'неизвестная ошибка\'), \'error\');\n    }\n  } catch(e) {\n    toast(\'❌ Ошибка соединения\', \'error\');\n  }\n\n  btn.disabled = false; btn.textContent = \'🔍 Запустить анализ\';\n}\n\n// ══════════════════════════════════════════════════\n// Отчёты и прочие действия\n// ══════════════════════════════════════════════════\nfunction downloadReport() {\n  window.open(\'/reports/active.xlsx\', \'_blank\');\n}\n\nasync function sendReport() {\n  toast(\'⏳ Формируем отчёт...\');\n  const res = await fetch(\'/reports/generate\', { method: \'POST\' });\n  const data = await res.json();\n  toast(\'✅ Отчёт отправлен в Telegram и Битрикс24!\', \'success\');\n}\n\nasync function triggerSource(key) {\n  const res = await fetch(\'/sources/trigger\', {\n    method: \'POST\',\n    headers: { \'Content-Type\': \'application/json\' },\n    body: JSON.stringify({ source_key: key })\n  });\n  const data = await res.json();\n  toast(\'↻ Мониторинг ЕИС запущен. ID: \' + data.task_id);\n}\n\nasync function markInactive() {\n  const res = await fetch(\'/tasks/mark-inactive\', { method: \'POST\' });\n  toast(\'⏰ Обновление дедлайнов запущено\');\n}\n\n\n// ══════════════════════════════════════════════════\n// Tender.Pro\n// ══════════════════════════════════════════════════\nfunction showPanel2(name) {\n  document.querySelectorAll(\'.panel\').forEach(p => p.classList.remove(\'active\'));\n  document.querySelectorAll(\'nav button\').forEach(b => b.classList.remove(\'active\'));\n  document.getElementById(\'panel-\' + name).classList.add(\'active\');\n  const btns = document.querySelectorAll(\'nav button\');\n  for (const b of btns) {\n    if (b.textContent.includes(\'Дашборд\')) { b.classList.add(\'active\'); break; }\n  }\n}\n\nasync function triggerTenderPro() {\n  toast(\'Запускаем мониторинг Tender.Pro...\');\n  try {\n    const res = await fetch(\'/sources/trigger\', {\n      method: \'POST\',\n      headers: {\'Content-Type\': \'application/json\'},\n      body: JSON.stringify({source_key: \'tender_pro\'})\n    });\n    const data = await res.json();\n    toast(\'Мониторинг Tender.Pro запущен! Задача: \' + data.task_id, \'success\');\n    setTimeout(loadTenderProStatus, 5000);\n  } catch(e) {\n    toast(\'Ошибка запуска\', \'error\');\n  }\n}\n\nasync function loadTenderProStatus() {\n  try {\n    const res = await fetch(\'/tenders/dashboard\');\n    const data = await res.json();\n    const tp = (data.tenders || []).filter(t => t.source === \'tender_pro\');\n    const statusEl = document.getElementById(\'tpStatus\');\n    const listEl = document.getElementById(\'tpList\');\n    if (statusEl) {\n      if (tp.length > 0) {\n        statusEl.innerHTML = \'Найдено тендеров Tender.Pro в базе: <strong>\' + tp.length + \'</strong>\';\n      } else {\n        statusEl.innerHTML = \'Тендеров с Tender.Pro ещё нет. Нажмите &laquo;Запустить проверку&raquo; или дождитесь автозапуска через 4 часа.\';\n      }\n    }\n    if (listEl) {\n      if (tp.length === 0) {\n        listEl.innerHTML = \'Нет данных\';\n      } else {\n        listEl.innerHTML = tp.slice(0,5).map(t =>\n          \'<div style="padding:8px 0;border-bottom:1px solid #f0f4f8">\' +\n          \'<strong>\' + sanitize(t.customer_name || t.external_id) + \'</strong><br>\' +\n          \'<span style="color:var(--sub)">\' + sanitize(t.title.substring(0,80)) + \'</span>\' +\n          \' &nbsp;<span class="status \' + t.status + \'">\' + t.status + \'</span>\' +\n          \'</div>\'\n        ).join(\'\');\n      }\n    }\n  } catch(e) {}\n}\n\n// Загружаем тендеры при старте\nloadTenders();\nloadTenderProStatus();\n</script>\n</body>\n</html>\n')]
