import argparse
import hashlib
import shutil
import subprocess
from datetime import datetime, timezone
from pathlib import Path

def run(args, **kwargs):
    subprocess.run(args, check=True, **kwargs)

def main():
    parser=argparse.ArgumentParser(description='Dashboard selection / participation separation. No DB or queue writes.')
    parser.add_argument('--check-only', action='store_true')
    args=parser.parse_args()
    root=Path.cwd()
    if not (root/'app/reports/active_tenders.py').is_file():
        raise SystemExit('Запустите из корня tender-ai-platform-v6.2')
    pending=[]
    for rel, expected, content in FILES:
        path=root/rel
        current=path.read_bytes()
        if current==content.encode(): continue
        if hashlib.sha256(current).hexdigest()!=expected:
            raise SystemExit('VERSION_MISMATCH: '+rel+'; изменения не внесены')
        if rel.endswith('.py'): compile(content,rel,'exec')
        pending.append((rel,content))
    print('VERSION_GUARDS_OK',flush=True)
    if args.check_only: return
    backup=root/'backups'/('dashboard-selection-'+datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S-%f'))
    if pending:
        for rel,content in pending:
            dest=backup/rel; dest.parent.mkdir(parents=True,exist_ok=True)
            shutil.copy2(root/rel,dest)
        for rel,content in pending:
            path=root/rel
            temp=path.with_suffix(path.suffix+'.dashboard-new')
            temp.write_text(content,encoding='utf-8');shutil.copymode(path,temp);temp.replace(path)
        print('BACKUP:',backup,flush=True)
    try:
        run(['docker','compose','build','app'])
        run(['docker','compose','run','--rm','--no-deps','-T','app','python','-'],input=TESTS,text=True)
    except Exception:
        for rel,_ in pending: shutil.copy2(backup/rel,root/rel)
        print('BUILD_OR_TEST_FAILED: source files restored; running containers not restarted',flush=True)
        raise
    run(['docker','compose','up','-d','--no-deps','--timeout','60','app'])
    print('DASHBOARD_SELECTION_INSTALLED',flush=True)
    print('No DB edits, LLM calls, tasks or notifications. Workers and schedules retained.',flush=True)
    run(['docker','compose','exec','-T','app','python','-'],input=AUDIT,text=True)

if __name__=='__main__': main()
